def cells(x,y,w,h,items,hi=None,soft=()):
    o=''
    for i,(a,v) in enumerate(items):
        c='bxa' if i==hi else ('soft' if i in soft else 'bx')
        o+=B(x,y+i*h,w,h,v,c,'t-s t-b' if i==hi else 't-s')+TL(x+w+6,y+i*h+h/2+4,a,'t-s mu')
    return o

def g1():
    o=B(10,44,84,44,'R1\n200 → 201','bxa','t-s t-b')
    o+=cells(210,10,70,32,[('200','21'),('201','23'),('202','22'),('203','24')],hi=0)
    o+=A(94,56,210,26)+T(140,30,'① оқу','t-s ac')
    o+=A(94,76,210,58,dash=True)+T(142,92,'② R1 := R1 + 1','t-s mu')
    return o
